import{_ as o,l as s,o as n,c as i,v as a,p as l,x as t,d as g,i as h,S as p}from"./chunks/framework.InCnrqk-.js";const v=JSON.parse('{"title":"Agent Lightning","description":"","frontmatter":{"title":"Agent Lightning","date":"2026-09-07T00:00:00.000Z","section":"llm"},"headers":[],"relativePath":"llm/agent-lightning.md","filePath":"llm/agent-lightning.md","lastUpdated":1789023840000}'),d={name:"llm/agent-lightning.md"};function m(L,e,c,A,u,R){const r=s("Mermaid");return n(),i("div",null,[e[1]||(e[1]=a('<h1 id="agent-lightning" tabindex="-1">Agent Lightning <a class="header-anchor" href="#agent-lightning" aria-label="Permalink to &quot;Agent Lightning&quot;">​</a></h1><div class="epigraph"><p>部署时用的 harness 直接参加后训练：训练引擎只看见一串 LLM 请求–响应，循环、工具和上下文策略仍归 harness 所有。</p><footer>—— He 等，Agent Lightning v1.0: Towards Harnessed Agentic RL，arXiv:2608.17528</footer></div><p>多数 RL 框架要求你把 agent 循环写进训练进程：ReAct 步、工具、拼 prompt 都在 rollout worker 里。真实产品里的循环已经写在 LangChain、AutoGen、OpenHands、Claude Code 一类 <strong>harness</strong> 里，再抄一遍既分叉又训用不一致。微软的 <strong>Agent Lightning</strong> 走代理注入：harness 仍打 OpenAI 式端点，端点其实是训练集群的代理，边转发边记轨迹。第一版 Luo、Zhang、He 等（arXiv:2508.03680）提出 Training-Agent Disaggregation 与 LightningRL。v1.0（He、Zhang、Zhou、Yang 等，arXiv:2608.17528，约 3500 行）把范式命名为 <strong>harnessed agentic RL</strong>，并诊断重分词、样本合并、优势与损失归一化。本篇钉「训练器注入 harness」指改的是 <strong>LLM 基址</strong>，不是把 VeRL 嵌进 agent 代码；钉 SWE-bench Verified 上 41.8%→56.4% 必须连着 6K 样本与 Qwen3.5-9B 读。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>传统 agentic RL 里，训练引擎拥有环境环：下一步 prompt 在 token 空间里是 \\(p_t=(p_{t-1},a_{t-1},o_t)\\)，一条 rollout 天然是一条线性 token 轨迹。Harness 介入后，潜在状态变成 \\((s^{\\mathrm{harness}}, s^{\\mathrm{env}})\\)。Harness 每次<strong>单独构造</strong>发给模型的消息，策略只看见 API 上的 \\((p_i,a_i)\\) 序列。子 agent、摘要压缩、重试都会让一次任务对应动态数量的训练样本。若仍按「一条 rollout = 一条序列」做组内优势，长短任务的梯度权重会偏。</p><p>工程上，把 OpenHands 嵌进 Ray worker 会把依赖和调度绑死。Luo 等人的目标是 <strong>几乎零改动</strong>：agent 继续用原框架，只把 base URL 指到 Lightning。v1.0 发现代理范式被 verl Uni-Agent、AReaL 2.0、slime v0.3.0、Polar 跟进后，真正没写清的是：文本 API 与 token 训练之间如何拼样本。</p><h3 id="重分词会拆掉「可合并」假设" tabindex="-1">重分词会拆掉「可合并」假设 <a class="header-anchor" href="#重分词会拆掉「可合并」假设" aria-label="Permalink to &quot;重分词会拆掉「可合并」假设&quot;">​</a></h3><p>框架常在 token 级检查 \\(p_{i+1}\\) 是否以 \\((p_i,a_i)\\) 为前缀，是则并成一条长序列。但 harness 传的是文本；再 tokenize 一次后，即使字符串相同，\\(a_i\\) 的 token 也可能与采样时不同（特殊符号、前后空白、chat template）。合并会把 logprob 对到错误 id 上。v1.0 把这列为 harnessed RL 的一等故障，而不是 tokenizer 边角。正确做法是训练只用<strong>模型采样时返回的 token</strong>，必要时放弃合并，改成多次调用、在 rollout 级做优势。见 <a href="/llm/agentloop-server">token 级 API</a> 与 <a href="/llm/multiturn-loss-mask">loss mask</a>。</p><p><span class="marginnote">v0.x 与 v1.0 是一次重构。引用实验时对版本。旧文的 text-to-SQL / RAG / 数学工具任务证明「能训」；v1.0 的 SWE 数字证明「harness 级编码代理能涨分」，不要混成同一张表。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>v1.0 三件套。<strong>Trainer</strong> 基于 VeRL + vLLM：登记 rollout、组装样本、更新策略。<strong>API Gateway</strong> 存 rollout 与事件，把 harness 的 LLM 调用转到当前模型端点并记录精确的 prompt/response token。<strong>Rollout Controller</strong> 在 Kubernetes Job 或本地进程池里拉起 harness，与训练集群可异地。Harness 只需把 endpoint 换成代理。样本适配器在 <strong>rollout 级</strong>算优势与损失归一，而不是按动态拆开的 sample 计数给长任务十倍权重。</p><p>LightningRL（2508.03680）把轨迹拆成转移：每步状态是该次 LLM 输入，动作是输出，再加信用分配，使现有单轮 PPO/GRPO 能吃多调用数据。AIR（Automatic Intermediate Rewarding）允许用工具返回码等监控信号给中间转移打分，缓解稀疏终点奖励。v1.0 强调这些选择现在必须在「调用序列」而不是「单条拼接序列」上定义。</p><p>SWE 实验：基于开源 SWE-smith 清洗出约 <strong>6K</strong> 训练例，Qwen3.5-9B，仅 RL，SWE-bench Verified <strong>41.8% → 56.4%</strong>（+14.6 个点）。作者同时指出现有 RL 框架对编码 agent 的数据与脚本支持弱、往往假设大规模算力；他们把清洗流水线与脚本公开，作为可复现的 harnessed 设定，而不是宣称通用 SOTA。第一版还在 text-to-SQL（LangChain）、RAG（OpenAI Agents SDK）、数学工具（AutoGen）上展示奖励曲线持续上升，用来证明「任意框架写出的 agent 都能接到同一训练服务」，任务分数应回引 2508.03680 的设定，不要与 v1.0 的 SWE 表合并。</p>',13)),(n(),l(p,null,{default:t(()=>[h(r,{id:"mermaid-37",class:"mermaid",graph:"flowchart%20TB%0A%20%20H%5B%22%E5%8E%9F%E6%9C%89%20Agent%20Harness%22%5D%20--%3E%7C%22OpenAI%20%E5%BC%8F%20API%22%7C%20GW%5B%22API%20Gateway%20%E4%BB%A3%E7%90%86%22%5D%0A%20%20RC%5B%22Rollout%20Controller%22%5D%20--%3E%20H%0A%20%20TR%5B%22Trainer%20%C2%B7%20VeRL%22%5D%20--%3E%20GW%0A%20%20GW%20--%3E%7C%22%E4%BA%8B%E4%BB%B6%20%2F%20token%22%7C%20TR%0A%20%20RC%20--%3E%20GW%0A"})]),fallback:t(()=>[...e[0]||(e[0]=[g(" Loading... ",-1)])]),_:1})),e[2]||(e[2]=a('<h3 id="注入点在端点-不在梯度公式" tabindex="-1">注入点在端点，不在梯度公式 <a class="header-anchor" href="#注入点在端点-不在梯度公式" aria-label="Permalink to &quot;注入点在端点，不在梯度公式&quot;">​</a></h3><p>「零改动」指控制流、工具协议、上下文策略不在训练仓库里重写。梯度仍然要 mask、优势、归一化；这些在 Gateway 之后做。若 harness 自己再本地 tokenizer 一遍拿去比对，会把 Lightning 记的 token 弄乱。集成测试应断言：训练 batch 里的 response id 与推理引擎返回的 id 一致。</p><p><span class="marginnote">代码约 3500 行是 v1.0 的设计声明，用来强调可审计，不是与 verl 三万行比「更完整」。功能集故意窄：代理、记账、rollout 级统计。</span></p><h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>Disaggregation 把 GPU 训练与 CPU/K8s 上的 agent 执行解耦，环境安装、浏览器、仓库克隆不再占训练镜像。可观测性栈（OpenTelemetry）能接到同一事件流，AIR 才有信号可写。代价是：训练引擎对 harness 内部状态不可见，信用分配只能在调用边界上做，不能在 harness 私有的「计划树」节点上做——除非 harness 把那些节点也变成 LLM 调用。</p><p>Rollout 级优势针对的病是：一次 SWE 任务被拆成 20 次 sample，一次检索任务拆成 2 次，若按 sample 平均，编码任务梯度被放大。按 rollout 归约后，任务才是可比的 i.i.d. 单位。这与 GRPO 按「同一问题的 G 条输出」分组不冲突，但分组键必须是任务 id，不是拆开后的调用 id。损失归一化同样：batch 里 sample 数随 harness 动态变化，训练 GPU 数却是固定的，后端要把变长样本集切成 step 与 micro-batch。v1.0 把调度也列为 harnessed RL 的挑战，而不是只改损失公式。</p><h3 id="和-verltool、agentloop-的分工" tabindex="-1">和 VerlTool、AgentLoop 的分工 <a class="header-anchor" href="#和-verltool、agentloop-的分工" aria-label="Permalink to &quot;和 VerlTool、AgentLoop 的分工&quot;">​</a></h3><p><a href="/llm/verltool">VERLTool</a> 把工具放进 VeRL 可调用的服务器，循环仍在训练框架的 AgentLoop 里。<a href="/llm/agentloop-server">AgentLoop</a> 是 VeRL 内部的多轮接口，假定你愿意实现 <code>run()</code>。Lightning 假定你<strong>不愿意</strong>实现第二份循环。三者都处理观察与 mask，所有权不同：工具服务器、框架内循环、框架外 harness。选错会重复造环境。</p><h2 id="边界与工程取舍" tabindex="-1">边界与工程取舍 <a class="header-anchor" href="#边界与工程取舍" aria-label="Permalink to &quot;边界与工程取舍&quot;">​</a></h2><p>不要把 14.6 个点写成「换框架就涨」。数据清洗、环境、基座模型都在条件里。不要假设任意 harness 的副作用（计费 API、写生产库）适合在 RL 里无沙箱滚动。代理增加一跳延迟；同步 RL 步可能被最慢的 K8s Job 钉住，需要超时与重试策略。Retokenization 未处理时，开异步只会让错误样本更多。多 agent 握手在 v1.0 里被列为与单 ReAct 不同的建模，实现深度以当时代码为准。</p><p>许可证 MIT；引用同时给 2508.03680 与 2608.17528，并写清实验来自哪一篇。</p><p><span class="marginnote">Luo 等 <em>Agent Lightning: Train ANY AI Agents with Reinforcement Learning</em>，arXiv:2508.03680。He 等 <em>Agent Lightning v1.0</em>，arXiv:2608.17528。Trainer 依赖 VeRL（Sheng 等 HybridFlow）。SWE-bench 协议应回引 Jimenez 等，不要把 Verified 子集分数与全量混报。</span></p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>Agent Lightning 用 LLM 代理把原有 harness 接到 RL，训练与执行分集群，几乎不改 agent 代码。</li><li>Harnessed RL 的样本是调用序列；必须处理重分词、动态 sample 数，以及 rollout 级优势与归一化。</li><li>v1.0 在 Qwen3.5-9B + 6K 例上把 SWE-bench Verified 从 41.8% 拉到 56.4%。</li><li>出处：arXiv:2508.03680、arXiv:2608.17528；<a href="https://github.com/microsoft/agent-lightning%E3%80%82" target="_blank" rel="noreferrer">https://github.com/microsoft/agent-lightning。</a></li></ul>',14))])}const b=o(d,[["render",m]]);export{v as __pageData,b as default};
